#!/usr/bin/env python3
# Map (grep -n a name to jump there):
#   Tables            style.json's toolkit half resolved: kinds, states, tokens, specs
#   generate          moy_ui_tables.h and .c from style.json
#   generate_theme    the theme loader's tables: limits, rules, pairs, luminance, seeds
#   _recolour         the accent-and-tint derivation's tables (accents, tints, classes)
#   generate_strings  the string table (strings/en.json)
#   outputs           every generated file and its text (the drift test reads it)
"""Write the toolkit's tables from their data (docs/kernel_toolkit_2026-10.md
§2.1): native/moy_ui's `style.json` in, its `moy_ui_tables.h` and
`moy_ui_tables.c` out, the seed theme packages (`themes/*.json`) embedded in
them; native/moy_spine's `strings/en.json` in, its
`moy_str_table.h` and `moy_str_table.c` out. The output is committed: no build
runs this, and tests/test_ui_tables.py regenerates it and fails on any
difference.

    python3 tools/gen_ui_tables.py [--dir native/moy_ui] [--str-dir native/moy_spine] [--check]
"""

import argparse
import json
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DIR = os.path.join(ROOT, "native", "moy_ui")
STR_DIR = os.path.join(ROOT, "native", "moy_spine")


def _c_str(s):
    out = []
    for ch in s.encode("utf-8"):
        c = chr(ch)
        if c in '"\\':
            out.append("\\" + c)
        elif 32 <= ch < 127:
            out.append(c)
        else:
            out.append("\\%03o" % ch)
    return '"' + "".join(out) + '"'


def _ident(name):
    return re.sub(r"[^A-Z0-9]", "_", name.upper())


class Tables:
    def __init__(self, style):
        self.style = style
        self.tokens = list(style["tokens"])
        self.aliases = list(style["aliases"])
        self.roles = self.tokens + self.aliases
        self.states = list(style["states"])
        ckinds = list(style["kinds"])
        mkinds = [k for k in style["metrics"] if k not in ckinds]
        self.kinds = ckinds + mkinds
        self.specs = [()]                    # spec 0: paint nothing
        self.spec_ix = {(): 0}

    def role(self, name):
        if name not in self.roles:
            raise SystemExit("style.json: %r is no token and no alias" % name)
        return self.roles.index(name)

    def term(self, s):
        if isinstance(s, bool) or not isinstance(s, (int, str)):
            raise SystemExit("style.json: a chain holds %r" % (s,))
        if isinstance(s, int):
            if not 0 <= s < 64:
                raise SystemExit("style.json: palette index %d" % s)
            return s
        return -1 - self.role(s)

    def spec(self, s):
        if s is None:
            terms = ()
        elif isinstance(s, list):
            terms = tuple(self.term(x) for x in s)
        else:
            terms = (self.term(s),)
        if len(terms) > 3:
            raise SystemExit("style.json: a chain longer than 3: %r" % (s,))
        if terms not in self.spec_ix:
            self.spec_ix[terms] = len(self.specs)
            self.specs.append(terms)
        return self.spec_ix[terms]

    def kind_specs(self):
        rows = []
        for k in self.kinds:
            states = self.style["kinds"].get(k)
            row = []
            for st in self.states:
                triple = None if states is None else states.get(st)
                if triple is None:
                    row.append(None)
                else:
                    row.append(tuple(self.spec(x) for x in triple))
            rows.append(row)
        return rows

    def metrics(self):
        out = []
        for k in self.kinds:
            slots = self.style["metrics"].get(k)
            out.append(None if slots is None else list(slots.values()))
        return out


def generate(style, d=DIR):
    t = Tables(style)
    t.dir = d
    nslot = max(len(v) for v in style["metrics"].values())
    rows, mets = t.kind_specs(), t.metrics()
    floors = style.get("floors", {})
    nfloor = max([len(v) for v in floors.values()] + [1])
    floor_rows = []
    for k in t.kinds:
        alts = [tuple(t.spec(x) for x in alt) for alt in floors.get(k, ())]
        floor_rows.append(alts)
    if any(k not in t.kinds for k in floors):
        raise SystemExit("style.json: a floor for a kind it does not name")
    h = []
    h.append("// GENERATED by tools/gen_ui_tables.py from style.json.")
    h.append("// Do not edit: change the data and regenerate "
             "(tests/test_ui_tables.py).")
    h.append("#ifndef MOY_UI_TABLES_H\n#define MOY_UI_TABLES_H\n")
    h.append("#include <stdint.h>\n")
    h.append("#define MOY_UI_TOKENS %d" % len(t.tokens))
    h.append("#define MOY_UI_ROLES %d" % len(t.roles))
    h.append("#define MOY_UI_STATES %d" % len(t.states))
    h.append("#define MOY_UI_KINDS %d" % len(t.kinds))
    h.append("#define MOY_UI_COLOR_KINDS %d" % len(style["kinds"]))
    h.append("#define MOY_UI_SLOTS %d" % nslot)
    h.append("#define MOY_UI_SPECS %d" % len(t.specs))
    h.append("#define MOY_UI_GLYPHS %d" % len(style["glyphs"]))
    h.append("#define MOY_UI_GLYPH_SIZE %d" % style["glyph_size"])
    h.append("")
    h.append("// The tokens, in the row's order.")
    h.append("enum {")
    for i, tok in enumerate(t.tokens):
        h.append("    MOY_UI_T_%s = %d," % (_ident(tok), i))
    h.append("};\n")
    h.append("// The states, strongest first (widget_state's precedence).")
    h.append("enum {")
    for i, st in enumerate(t.states):
        h.append("    MOY_UI_%s = %d," % (_ident(st), i))
    h.append("};\n")
    h.append("// The kinds: those a style entry colours, then those with only "
             "metrics.")
    h.append("enum {")
    for i, k in enumerate(t.kinds):
        h.append("    MOY_UI_K_%s = %d," % (_ident(k), i))
    h.append("};\n")
    h.append("// Each kind's metric slots.")
    h.append("enum {")
    for k, slots in style["metrics"].items():
        for i, s in enumerate(slots):
            h.append("    MOY_UI_M_%s_%s = %d," % (_ident(k), _ident(s), i))
    h.append("};\n")
    h.append("typedef struct { int8_t n; int8_t t[3]; } moy_ui_spec_t;")
    h.append("extern const int moy_ui_n_tokens, moy_ui_n_roles, moy_ui_n_states, "
             "moy_ui_n_kinds,")
    h.append("    moy_ui_n_color_kinds, moy_ui_n_glyphs;")
    h.append("extern const char *const moy_ui_token_names[MOY_UI_TOKENS];")
    h.append("extern const char *const moy_ui_role_names[MOY_UI_ROLES];")
    h.append("extern const int8_t moy_ui_alias[MOY_UI_ROLES - MOY_UI_TOKENS][3];")
    h.append("extern const char *const moy_ui_state_names[MOY_UI_STATES];")
    h.append("extern const char *const moy_ui_kind_names[MOY_UI_KINDS];")
    h.append("extern const char *const moy_ui_button_kinds[%d][2];"
             % len(style["button_kinds"]))
    h.append("#define MOY_UI_BUTTON_KINDS %d" % len(style["button_kinds"]))
    h.append("extern const moy_ui_spec_t moy_ui_specs[MOY_UI_SPECS];")
    h.append("// [kind][state][field, ink, edge]: a spec index, or 0xff "
             "where the kind names no such state.")
    h.append("extern const uint8_t moy_ui_kind_specs[MOY_UI_KINDS]"
             "[MOY_UI_STATES][3];")
    h.append("// [kind]: the (field, ink) specs its own states (rest, hover, hot) take,")
    h.append("// in order, where their pair misses the contrast floor; the count first.")
    h.append("#define MOY_UI_FLOORS %d" % nfloor)
    h.append("extern const uint8_t moy_ui_floor_n[MOY_UI_KINDS];")
    h.append("extern const uint8_t moy_ui_floor_specs[MOY_UI_KINDS][MOY_UI_FLOORS][2];")
    h.append("// [kind]: the slot count (0: no metrics), then the values.")
    h.append("extern const uint8_t moy_ui_metric_n[MOY_UI_KINDS];")
    h.append("extern const int16_t moy_ui_metric_vals[MOY_UI_KINDS][MOY_UI_SLOTS];")
    h.append("extern const char *const moy_ui_metric_slots[MOY_UI_KINDS];")
    h.append("// The glyph vocabulary: each glyph's rows, bit (size - 1 - col) the ink.")
    h.append("extern const char *const moy_ui_glyph_names[MOY_UI_GLYPHS];")
    h.append("extern const uint16_t moy_ui_glyph_rows[MOY_UI_GLYPHS][MOY_UI_GLYPH_SIZE];")
    h.append("\n#endif // MOY_UI_TABLES_H")

    if len(t.specs) >= 255:
        raise SystemExit("more than 255 distinct token specs")
    c = []
    c.append("// GENERATED by tools/gen_ui_tables.py from style.json.")
    c.append("// Do not edit: change the data and regenerate "
             "(tests/test_ui_tables.py).\n")
    c.append('#include "moy_ui_tables.h"\n')
    c.append("// The counts, for a binding that reads the tables by symbol.")
    for k in ("tokens", "roles", "states", "kinds", "color_kinds", "glyphs"):
        c.append("const int moy_ui_n_%s = MOY_UI_%s;" % (k, k.upper()))
    c.append("")

    def names(decl, seq):
        c.append("%s = {" % decl)
        for s in seq:
            c.append("    %s," % _c_str(s))
        c.append("};\n")

    names("const char *const moy_ui_token_names[MOY_UI_TOKENS]", t.tokens)
    names("const char *const moy_ui_role_names[MOY_UI_ROLES]", t.roles)
    c.append("const int8_t moy_ui_alias[MOY_UI_ROLES - MOY_UI_TOKENS][3] = {")
    for a in t.aliases:
        chain = [t.tokens.index(x) for x in style["aliases"][a]]
        if len(chain) > 3 or any(x not in t.tokens for x in style["aliases"][a]):
            raise SystemExit("alias %s: a chain of tokens, at most 3" % a)
        chain += [-1] * (3 - len(chain))
        c.append("    {%s},  // %s" % (", ".join(map(str, chain)), a))
    c.append("};\n")
    names("const char *const moy_ui_state_names[MOY_UI_STATES]", t.states)
    names("const char *const moy_ui_kind_names[MOY_UI_KINDS]", t.kinds)
    c.append("const char *const moy_ui_button_kinds[%d][2] = {"
             % len(style["button_kinds"]))
    for k, v in style["button_kinds"].items():
        c.append("    {%s, %s}," % (_c_str(k), _c_str(v)))
    c.append("};\n")
    c.append("const moy_ui_spec_t moy_ui_specs[MOY_UI_SPECS] = {")
    for terms in t.specs:
        pad = list(terms) + [0] * (3 - len(terms))
        c.append("    {%d, {%s}}," % (len(terms), ", ".join(map(str, pad))))
    c.append("};\n")
    c.append("const uint8_t moy_ui_kind_specs[MOY_UI_KINDS][MOY_UI_STATES][3] = {")
    for k, row in zip(t.kinds, rows):
        cells = ", ".join("{0xff, 0xff, 0xff}" if tr is None else
                          "{%d, %d, %d}" % tr for tr in row)
        c.append("    {%s},  // %s" % (cells, k))
    c.append("};\n")
    c.append("const uint8_t moy_ui_floor_n[MOY_UI_KINDS] = {%s};\n" % ", ".join(
        str(len(f)) for f in floor_rows))
    c.append("const uint8_t moy_ui_floor_specs[MOY_UI_KINDS][MOY_UI_FLOORS][2] = {")
    for k, alts in zip(t.kinds, floor_rows):
        cells = list(alts) + [(0, 0)] * (nfloor - len(alts))
        c.append("    {%s},  // %s" % (", ".join("{%d, %d}" % a for a in cells), k))
    c.append("};\n")
    c.append("const uint8_t moy_ui_metric_n[MOY_UI_KINDS] = {%s};\n" % ", ".join(
        str(len(style["metrics"].get(k, {}))) for k in t.kinds))
    c.append("const int16_t moy_ui_metric_vals[MOY_UI_KINDS][MOY_UI_SLOTS] = {")
    for k, vals in zip(t.kinds, mets):
        v = (vals or []) + [0] * (nslot - len(vals or []))
        c.append("    {%s},  // %s" % (", ".join(map(str, v)), k))
    c.append("};\n")
    names("const char *const moy_ui_metric_slots[MOY_UI_KINDS]",
          [" ".join(style["metrics"].get(k, {})) for k in t.kinds])
    gs = style["glyph_size"]
    if gs > 16:
        raise SystemExit("a glyph row is a uint16: glyph_size %d" % gs)
    names("const char *const moy_ui_glyph_names[MOY_UI_GLYPHS]", list(style["glyphs"]))
    c.append("const uint16_t moy_ui_glyph_rows[MOY_UI_GLYPHS][MOY_UI_GLYPH_SIZE] = {")
    for k, rows in style["glyphs"].items():
        if len(rows) != gs or any(len(r) != gs or set(r) - set("#.") for r in rows):
            raise SystemExit("glyph %s: %d rows of %d '#'/'.'" % (k, gs, gs))
        vals = [sum(1 << (gs - 1 - i) for i, ch in enumerate(r) if ch == "#")
                for r in rows]
        c.append("    {%s},  // %s" % (", ".join("0x%03X" % v for v in vals), k))
    c.append("};\n")
    th, tc = generate_theme(style, t)
    h[-1:-1] = th
    c.extend(tc)
    return "\n".join(h) + "\n", "\n".join(c)


def _luminance():
    """MOY64's relative luminance (WCAG), x10000, from runtime/palette.py."""
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        "_moy64", os.path.join(ROOT, "runtime", "palette.py"))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)

    def lin(v):
        v /= 255.0
        return v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4
    return [round(10000 * (0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b)))
            for r, g, b in mod.MOY64]


def generate_theme(style, t):
    """The theme loader's tables (native/moy_ui/moy_theme.c): format 1's
    limits, the derivation rules, the readability pairs, MOY64's luminance and
    the seed packages' bytes."""
    th = style["theme"]
    lay = th["layout"]
    if len(lay["widgets"]) > 16 or len(lay["edges"]) > 4 or lay["size"][1] > 255:
        raise SystemExit("theme.layout: a widget is a bit of 16, an edge one of 4, a size a byte")
    seeds = []
    for name in th["seeds"]:
        with open(os.path.join(t.dir, "themes", name + ".json"), "rb") as f:
            src = f.read()
        pkg = json.loads(src)
        if pkg.get("name") != name or len(src) > th["bytes"]:
            raise SystemExit("themes/%s.json: named %s, within %d bytes"
                             % (name, name, th["bytes"]))
        seeds.append((name, src))
    # The seed packages' files: every font a seed's `fonts` names and each
    # of `preset_fonts` (Appearance's Font presets) and, as in a published
    # package, its licence's full text X.txt beside X.fnt, from themes/, in
    # name order. A face of the font set (fonts/, which each board image
    # carries per tier: runtime/fontset.py) is not embedded a second time.
    font_set = os.path.join(t.dir, "fonts")
    font_files = sorted({f for _n, src in seeds
                         for f in json.loads(src).get("fonts", {}).values()}
                        .union(th["preset_fonts"])
                        - {f for f in os.listdir(font_set)})
    fonts = []
    for name in sorted(font_files + [f[:-len(".fnt")] + ".txt" for f in font_files]):
        path = os.path.join(t.dir, "themes", name)
        if not os.path.isfile(path):
            raise SystemExit("themes/%s: a seed's font ships its licence's full text "
                             "beside it, and this is missing" % name)
        with open(path, "rb") as f:
            fonts.append((name, f.read()))
    root_pkg = json.loads(seeds[0][1])
    root = root_pkg["colors"]
    roles = t.tokens + list(th["content"])
    if set(roles) & set(t.aliases) or len(set(roles)) != len(roles):
        raise SystemExit("theme.content: a role named twice")
    metrics = list(th["metrics"])
    missing = [m for m in metrics if m not in root_pkg.get("metrics", {})]
    if missing:
        raise SystemExit("the default theme leaves metrics %s unset" % missing)
    rules, at, flags = [], [], [0] * len(roles)
    for v in ("dark", "light", "both"):
        at.append((len(rules), len(th["derive"][v])))
        for role, val in th["derive"][v]:
            r = roles.index(role)
            if isinstance(val, bool):
                flags[r] = 1
                rules.append((r, 0, int(val)))
            elif isinstance(val, int):
                rules.append((r, 0, val))
            else:
                rules.append((r, 1, roles.index(val)))
    derived = {roles[r] for r, _k, _v in rules}
    for v in ("dark", "light"):
        missing = [k for k in roles if k not in derived and k not in root[v]]
        if missing:
            raise SystemExit("the default theme's %s leaves %s unset" % (v, missing))
    parts = t.kinds + list(th["parts"])
    states = t.states + list(th["states"])
    if len(set(parts)) != len(parts) or len(set(states)) != len(states):
        raise SystemExit("theme.parts / theme.states: a name twice")
    nxt = []
    for st in states:
        if st == "rest":
            nxt.append(255)
            continue
        seen, cur = set(), st
        while cur != "rest":
            if cur in seen or th["chain"].get(cur) not in states:
                raise SystemExit("theme.chain: %s does not end at rest" % st)
            seen.add(cur)
            cur = th["chain"][cur]
        nxt.append(states.index(th["chain"][st]))
    sheet_keys = list(th["sheets"])
    for name, src in seeds:
        if set(sheet_keys) & set(json.loads(src)):
            raise SystemExit("themes/%s.json: a seed names no sheet (the tables embed none)"
                             % name)
    slots = th["sprite_slots"]
    if len(slots) != 16 or slots[0] is not None:
        raise SystemExit("theme.sprite_slots: sixteen, the first transparent (null)")
    slot_terms = ["INT8_MIN"]
    for v in slots[1:]:
        if isinstance(v, int) and 0 <= v < 64:
            slot_terms.append(str(v))
        elif v in t.tokens:
            slot_terms.append(str(-1 - t.tokens.index(v)))
        else:
            raise SystemExit("theme.sprite_slots: %r is no token and no palette index" % (v,))
    fb_names = th["frame_button_names"]
    cells, used = [], set()
    for part, st, sub, x, y, w, h_ in th["sprite_cells"]:
        nine = part in th["sprite_nine"]
        if part not in parts or st not in states:
            raise SystemExit("theme.sprite_cells: %s %s names no part and state" % (part, st))
        if (sub is None) != (part != "window.button") or (sub is not None
                                                          and sub not in fb_names):
            raise SystemExit("theme.sprite_cells: a title button names its button")
        if x < 0 or y < 0 or w < 1 or h_ < 1 or x + w > 16 or (nine and (w < 3 or h_ < 3)):
            raise SystemExit("theme.sprite_cells: %s %s is no cell of the sheet" % (part, st))
        tiles = {(x + i, y + j) for i in range(w) for j in range(h_)}
        if tiles & used:
            raise SystemExit("theme.sprite_cells: %s %s overlaps a cell" % (part, st))
        used |= tiles
        cells.append((parts.index(part), states.index(st),
                      fb_names.index(sub) if sub is not None else 0,
                      x * 8, y * 8, w * 8, h_ * 8, int(nine), part, st, sub))
    sheet_rows = max(c[4] + c[6] for c in cells)
    if th["sheet_rows"]["icons"] < 16 * -(-len(_icon_slots()) // 8):
        raise SystemExit("theme.sheet_rows: icons holds no tile for every icon slot")
    h = ["// Theme packages, format 1 (moy_theme.c): the limits, the derivation",
         "// rules, the readability pairs, MOY64's luminance and the seeds.",
         "#define MOY_THEME_FORMAT %d" % th["format"],
         "#define MOY_THEME_SEEDS %d" % len(seeds),
         "#define MOY_THEME_BYTES %d" % th["bytes"],
         "#define MOY_THEME_DEPTH %d" % th["depth"],
         "#define MOY_THEME_RULES %d" % len(rules),
         "#define MOY_THEME_PAIRS %d" % len(th["pairs"]),
         "#define MOY_THEME_CONTRAST %d" % th["contrast"],
         "// The code roles, each held to its own floor on the code surface; bit",
         "// MOY_THEME_PAIRS + 1 + i of the readability report is role i's.",
         "#define MOY_THEME_CODE %d" % len(th["code"]["roles"]),
         "#define MOY_THEME_CODE_BG %d" % roles.index(th["code"]["bg"]),
         "#define MOY_THEME_CODE_CONTRAST %d" % th["code"]["contrast"],
         "#define MOY_THEME_RESERVED %d" % len(th["reserved"]),
         "#define MOY_THEME_FONT_ROLES %d" % len(th["font_roles"]),
         "// The sheets a package may name (docs/theming_2026-09.md \u00a74.6), the",
         "// cart sheet's hex format: a line a row of up to MOY_THEME_SHEET_W nibbles,",
         "// at most each sheet's rows. The role sheet's cells, in pixels, reach",
         "// MOY_THEME_SPRITE_ROWS rows: what the loader keeps.",
         "#define MOY_THEME_SHEETS %d" % len(sheet_keys),
         "#define MOY_THEME_SHEET_SPRITES %d" % sheet_keys.index("sprites"),
         "#define MOY_THEME_SHEET_ICONS %d" % sheet_keys.index("icons"),
         "#define MOY_THEME_SHEET_W 128",
         "#define MOY_THEME_SPRITES_MAX_ROWS %d" % th["sheet_rows"]["sprites"],
         "#define MOY_THEME_ICONS_MAX_ROWS %d" % th["sheet_rows"]["icons"],
         "#define MOY_THEME_SLOT_BITS %d  // a `slots` leaf's icon slots" % SLOT_BITS,
         "#define MOY_THEME_SHEET_BYTES(rows) ((rows) * (MOY_THEME_SHEET_W + 2))",
         "#define MOY_THEME_SPRITE_ROWS %d" % sheet_rows,
         "#define MOY_THEME_SPRITE_SLOTS 16",
         "#define MOY_THEME_CELLS %d" % len(cells),
         "// A cell: its part, state and title button (frame_button_names), its",
         "// rect in pixels, and whether it is a 9-slice (8-pixel corners).",
         "typedef struct { uint8_t part, state, sub, x, y, w, h, nine; } moy_theme_cell_t;",
         "extern const moy_theme_cell_t moy_theme_cells[MOY_THEME_CELLS];",
         "// Each slot's colour: INT8_MIN transparent, a palette index, or -1 - a token.",
         "extern const int8_t moy_theme_sprite_slots[MOY_THEME_SPRITE_SLOTS];",
         "extern const char *const moy_theme_sheet_keys[MOY_THEME_SHEETS];",
         "#define MOY_THEME_FONT_FILES %d  // the seeds' fonts and their licence texts"
         % len(fonts),
         "#define MOY_THEME_ROLES %d  // the tokens, then the content roles" % len(roles),
         "#define MOY_THEME_METRICS %d" % len(metrics),
         "#define MOY_THEME_EFFECTS %d" % len(th["effects"]),
         "#define MOY_THEME_EFFECTS_CAP %d" % th["effects_cap"],
         "// What `text` and `surfaces` are keyed by: the kinds, then the chrome's",
         "// parts; the style's states, then a window's.",
         "#define MOY_THEME_PARTS %d" % len(parts),
         "#define MOY_THEME_STATES %d" % len(states),
         "#define MOY_THEME_EDGES %d" % len(th["edges"]),
         "#define MOY_THEME_FILLS %d" % len(th["fills"]),
         "#define MOY_THEME_SURFACES_CAP %d" % th["surfaces_cap"],
         "#define MOY_THEME_SURFACE_LEN %d" % th["surface_len"],
         "// A frame: its style, its title's alignment, its buttons' letters.",
         "#define MOY_THEME_FRAMES %d" % len(th["frames"]),
         "#define MOY_THEME_ALIGNS %d" % len(th["title_aligns"]),
         "#define MOY_THEME_FRAME_BUTTONS %s" % _c_str(th["frame_buttons"]),
         "// A layout (docs/shell_layout_2026-10.md \u00a75): its bars' edges, their",
         "// slots and the widget catalogue; the caps and the size clamp.",
         "#define MOY_THEME_BARS %d  // one per edge" % len(lay["edges"]),
         "#define MOY_THEME_SLOTS %d" % len(lay["slots"]),
         "#define MOY_THEME_WIDGETS %d" % len(lay["widgets"]),
         "#define MOY_THEME_SLOT_CAP %d" % lay["slot_cap"],
         "#define MOY_THEME_WIDGET_CAP %d" % lay["widget_cap"],
         "#define MOY_THEME_BAR_MIN %d" % lay["size"][0],
         "#define MOY_THEME_BAR_MAX %d" % lay["size"][1],
         "#define MOY_THEME_BAR_SIZE %d" % lay["size_default"],
         "#define MOY_THEME_TEXT_MAX %d" % lay["text_max"],
         "#define MOY_THEME_HOMES %d  // the home's arrangements, the first the default"
         % len(lay["homes"]),
         "#define MOY_THEME_W_REQUIRED 0x%xu  // a bit per widget" % sum(
             1 << lay["widgets"].index(w) for w in lay["required"]),
         "#define MOY_THEME_W_REPEATABLE 0x%xu" % sum(
             1 << lay["widgets"].index(w) for w in lay["repeatable"]),
         "enum {",
         *["    MOY_THEME_W_%s = %d," % (_ident(w), i) for i, w in enumerate(lay["widgets"])],
         "};",
         "enum {",
         *["    MOY_THEME_FRAME_%s = %d," % (_ident(f), i) for i, f in enumerate(th["frames"])],
         "};",
         "enum {",
         *["    MOY_THEME_ALIGN_%s = %d," % (_ident(a), i)
           for i, a in enumerate(th["title_aligns"])],
         "};",
         "enum {",
         *["    MOY_THEME_M_%s = %d," % (_ident(m), i) for i, m in enumerate(metrics)],
         "};",
         "enum {",
         *["    MOY_THEME_FX_%s = %d," % (_ident(e), i) for i, e in enumerate(th["effects"])],
         "};",
         "// The chrome's parts, after the kinds.",
         "enum {",
         *["    MOY_THEME_P_%s = %d," % (_ident(p), len(t.kinds) + i)
           for i, p in enumerate(th["parts"])],
         "};",
         "// The states past the style's.",
         "enum {",
         *["    MOY_THEME_S_%s = %d," % (_ident(st), len(t.states) + i)
           for i, st in enumerate(th["states"])],
         "};",
         "// A missing role's rule: `role` gets `v`, a palette index or flag, or",
         "// (is_role) the role `v`'s value.",
         "typedef struct { uint8_t role, is_role, v; } moy_theme_rule_t;",
         "extern const moy_theme_rule_t moy_theme_rules[MOY_THEME_RULES];",
         "// [dark, light, both]: (first rule, count).",
         "extern const uint8_t moy_theme_rules_at[3][2];",
         "extern const uint8_t moy_theme_flag[MOY_THEME_ROLES];",
         "extern const char *const moy_theme_role_names[MOY_THEME_ROLES];",
         "extern const char *const moy_theme_metric_names[MOY_THEME_METRICS];",
         "// each metric's [min, max]",
         "extern const int8_t moy_theme_metric_range[MOY_THEME_METRICS][2];",
         "extern const char *const moy_theme_effect_names[MOY_THEME_EFFECTS];",
         "extern const char *const moy_theme_part_names[MOY_THEME_PARTS];",
         "extern const char *const moy_theme_state_names[MOY_THEME_STATES];",
         "// The state a state falls back to when a part does not name it; rest: 255.",
         "extern const uint8_t moy_theme_state_next[MOY_THEME_STATES];",
         "extern const char *const moy_theme_edge_names[MOY_THEME_EDGES];",
         "extern const char *const moy_theme_fill_names[MOY_THEME_FILLS];",
         "extern const char *const moy_theme_frame_names[MOY_THEME_FRAMES];",
         "extern const char *const moy_theme_align_names[MOY_THEME_ALIGNS];",
         "extern const uint8_t moy_theme_pairs[MOY_THEME_PAIRS][2];",
         "extern const uint8_t moy_theme_code[MOY_THEME_CODE];",
         "extern const uint16_t moy_theme_lum[64];",
         "extern const char *const moy_theme_reserved[MOY_THEME_RESERVED];",
         "extern const char *const moy_theme_font_roles[MOY_THEME_FONT_ROLES];",
         "extern const char *const moy_theme_bar_edges[MOY_THEME_BARS];",
         "extern const char *const moy_theme_slot_names[MOY_THEME_SLOTS];",
         "extern const char *const moy_theme_widget_names[MOY_THEME_WIDGETS];",
         "extern const char *const moy_theme_home_names[MOY_THEME_HOMES];",
         "extern const char *const moy_theme_seed_names[MOY_THEME_SEEDS];",
         "extern const char *const moy_theme_seed_src[MOY_THEME_SEEDS];",
         "extern const uint16_t moy_theme_seed_len[MOY_THEME_SEEDS];",
         "extern const char *const moy_theme_font_names[MOY_THEME_FONT_FILES + 1];",
         "extern const uint8_t *const moy_theme_font_data[MOY_THEME_FONT_FILES + 1];",
         "extern const uint16_t moy_theme_font_len[MOY_THEME_FONT_FILES + 1];",
         "extern const int moy_ui_n_themes, moy_theme_n_roles, moy_theme_n_metrics,",
         "    moy_theme_n_effects, moy_theme_n_parts, moy_theme_n_states, moy_theme_n_font_roles,"
         "\n    moy_theme_n_homes;"]
    rh, rc = _recolour(th, roles, flags)
    h.extend(rh)
    lh, lc = _look(th, roles)
    h.extend(lh)
    rc = rc + lc
    c = ["const moy_theme_rule_t moy_theme_rules[MOY_THEME_RULES] = {"]
    for r, k, v in rules:
        c.append("    {%d, %d, %d},  // %s" % (r, k, v, roles[r]))
    c.append("};\n")
    c.append("const uint8_t moy_theme_rules_at[3][2] = {%s};\n"
             % ", ".join("{%d, %d}" % a for a in at))
    c.append("const uint8_t moy_theme_flag[MOY_THEME_ROLES] = {%s};\n"
             % ", ".join(map(str, flags)))
    c.append("const char *const moy_theme_role_names[MOY_THEME_ROLES] = {")
    c.extend("    %s," % _c_str(r) for r in roles)
    c.append("};\n")
    c.append("const char *const moy_theme_metric_names[MOY_THEME_METRICS] = {")
    c.extend("    %s," % _c_str(m) for m in metrics)
    c.append("};\n")
    c.append("const int8_t moy_theme_metric_range[MOY_THEME_METRICS][2] = {%s};\n"
             % ", ".join("{%d, %d}" % tuple(th["metrics"][m]) for m in metrics))
    c.append("const char *const moy_theme_effect_names[MOY_THEME_EFFECTS] = {")
    c.extend("    %s," % _c_str(e) for e in th["effects"])
    c.append("};\n")
    for decl, seq in (("moy_theme_part_names[MOY_THEME_PARTS]", parts),
                      ("moy_theme_state_names[MOY_THEME_STATES]", states),
                      ("moy_theme_edge_names[MOY_THEME_EDGES]", th["edges"]),
                      ("moy_theme_fill_names[MOY_THEME_FILLS]", th["fills"]),
                      ("moy_theme_frame_names[MOY_THEME_FRAMES]", th["frames"]),
                      ("moy_theme_align_names[MOY_THEME_ALIGNS]", th["title_aligns"]),
                      ("moy_theme_font_roles[MOY_THEME_FONT_ROLES]", th["font_roles"]),
                      ("moy_theme_bar_edges[MOY_THEME_BARS]", lay["edges"]),
                      ("moy_theme_slot_names[MOY_THEME_SLOTS]", lay["slots"]),
                      ("moy_theme_widget_names[MOY_THEME_WIDGETS]", lay["widgets"]),
                      ("moy_theme_home_names[MOY_THEME_HOMES]", lay["homes"])):
        c.append("const char *const %s = {" % decl)
        c.extend("    %s," % _c_str(n) for n in seq)
        c.append("};\n")
    c.append("const uint8_t moy_theme_state_next[MOY_THEME_STATES] = {%s};\n"
             % ", ".join(map(str, nxt)))
    c.append("const uint8_t moy_theme_pairs[MOY_THEME_PAIRS][2] = {")
    for a, b in th["pairs"]:
        c.append("    {%d, %d},  // %s / %s" % (roles.index(a), roles.index(b), a, b))
    c.append("};\n")
    c.append("const uint8_t moy_theme_code[MOY_THEME_CODE] = {")
    for r in th["code"]["roles"]:
        c.append("    %d,  // %s" % (roles.index(r), r))
    c.append("};\n")
    lum = _luminance()
    c.append("const uint16_t moy_theme_lum[64] = {")
    for i in range(0, 64, 8):
        c.append("    %s," % ", ".join("%5d" % v for v in lum[i:i + 8]))
    c.append("};\n")
    c.append("const char *const moy_theme_reserved[MOY_THEME_RESERVED] = {")
    c.extend("    %s," % _c_str(k) for k in th["reserved"])
    c.append("};\n")
    c.append("const moy_theme_cell_t moy_theme_cells[MOY_THEME_CELLS] = {")
    for cl in cells:
        c.append("    {%d, %d, %d, %d, %d, %d, %d, %d},  // %s %s%s"
                 % (cl[:8] + (cl[8], cl[9], " " + cl[10] if cl[10] else "")))
    c.append("};\n")
    c.append("const int8_t moy_theme_sprite_slots[MOY_THEME_SPRITE_SLOTS] = {%s};\n"
             % ", ".join(slot_terms))
    c.append("const char *const moy_theme_sheet_keys[MOY_THEME_SHEETS] = {%s};\n"
             % ", ".join(_c_str(k) for k in sheet_keys))
    c.append("const char *const moy_theme_seed_names[MOY_THEME_SEEDS] = {")
    c.extend("    %s," % _c_str(n) for n, _s in seeds)
    c.append("};\n")
    c.append("const char *const moy_theme_seed_src[MOY_THEME_SEEDS] = {")
    for n, src in seeds:
        lines = src.decode("utf-8").splitlines(True)
        c.append("    // themes/%s.json" % n)
        c.extend("    %s" % _c_str(ln) for ln in lines[:-1])
        c.append("    %s," % _c_str(lines[-1]))
    c.append("};\n")
    c.append("const int moy_ui_n_themes = MOY_THEME_SEEDS;")
    c.append("const int moy_theme_n_roles = MOY_THEME_ROLES;")
    c.append("const int moy_theme_n_metrics = MOY_THEME_METRICS;")
    c.append("const int moy_theme_n_effects = MOY_THEME_EFFECTS;")
    c.append("const int moy_theme_n_parts = MOY_THEME_PARTS;")
    c.append("const int moy_theme_n_states = MOY_THEME_STATES;")
    c.append("const int moy_theme_n_font_roles = MOY_THEME_FONT_ROLES;")
    c.append("const int moy_theme_n_homes = MOY_THEME_HOMES;")
    c.append("const uint16_t moy_theme_seed_len[MOY_THEME_SEEDS] = {%s};\n"
             % ", ".join(str(len(s)) for _n, s in seeds))
    for i, (name, data) in enumerate(fonts):
        c.append("// themes/%s" % name)
        if name.endswith(".txt"):
            lines = data.decode("ascii").splitlines(True)
            c.append("static const uint8_t font_%d[%d] =" % (i, len(data) + 1))
            c.extend("    %s" % _c_str(ln) for ln in lines[:-1])
            c.append("    %s;" % _c_str(lines[-1]))
            continue
        c.append("static const uint8_t font_%d[%d] = {" % (i, len(data)))
        for k in range(0, len(data), 16):
            c.append("    %s," % ", ".join("0x%02x" % b for b in data[k:k + 16]))
        c.append("};")
    c.append("const char *const moy_theme_font_names[MOY_THEME_FONT_FILES + 1] = {%s0};"
             % "".join("%s, " % _c_str(n) for n, _d in fonts))
    c.append("const uint8_t *const moy_theme_font_data[MOY_THEME_FONT_FILES + 1] = {%s0};"
             % "".join("font_%d, " % i for i in range(len(fonts))))
    c.append("const uint16_t moy_theme_font_len[MOY_THEME_FONT_FILES + 1] = {%s0};\n"
             % "".join("%d, " % len(d) for _n, d in fonts))
    c.extend(rc)
    return h, c


def _moy64():
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        "_moy64", os.path.join(ROOT, "runtime", "palette.py"))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return list(mod.MOY64)


# A look leaf's kind, and a look field's type (moy_theme.h).
_LEAF_KINDS = ("colour", "paint", "enum", "int", "num", "bool", "text", "corners", "bits")
_FIELD_TYPES = ("colour", "paint", "enum", "int", "num", "bool", "text", "corners",
                "line", "shadow", "tshadow", "ring", "trio", "slots")
# A `slots` field's leaves: SLOT_BITS of the icon slots a leaf (a board's
# small int holds them), as many leaves as the pixel set's slots.txt needs.
SLOT_BITS = 30


def _icon_slots():
    """The icon slots, in order: the pixel set's slots.txt (moy_ui.c's table
    and runtime/iconsets.py's SLOTS are held to it)."""
    with open(os.path.join(ROOT, "native", "moy_ui", "icons", "pixel", "slots.txt")) as f:
        return [ln.split()[-1] for ln in f if ln.strip() and not ln.startswith("#")]


def _look_fields(lk, roles=()):
    """theme.look's fields with `buttons` expanded per kind: [(path, type,
    [(leaf name, kind, lo, hi, default), ...])]. A default None is NONE
    (silent: the renderer derives it); enum lo/hi are names, numbers are in
    hundredths; a `role` field is an enum of the theme's roles. A num's
    default may be a pair (light, dark): the leaf's default is the light
    one, and the dark one is a (leaf name, value) in the out list `dark`."""
    out = []

    def colour(v):
        if v is None:
            return None
        if not re.match(r"^#[0-9a-f]{6}$", v):
            raise SystemExit("theme.look: %r is no #rrggbb" % (v,))
        return 0x1000000 | int(v[1:], 16)

    def hund(v):
        return None if v is None else int(round(v * 100))

    dark = []

    def one(path, spec):
        t = spec[0]
        a = spec[1:]
        if t not in _FIELD_TYPES + ("role",):
            raise SystemExit("theme.look: %s has no type %r" % (path, t))
        if t == "colour":
            return [(path, "colour", 0, 0, colour(a[0] if a else None))]
        if t == "paint":
            return [(path, "paint", 0, 0, None)]
        if t == "enum":
            d = 0 if len(a) < 2 else a[1]
            return [(path, "enum", a[0], None, d)]
        if t == "role":
            d = a[0] if a else None
            if d is not None and d not in roles:
                raise SystemExit("theme.look: %s's default %r is no role" % (path, d))
            return [(path, "enum", list(roles), None, d)]
        if t == "int":
            return [(path, "int", a[0], a[1], a[2] if len(a) > 2 else None)]
        if t == "num":
            d = a[2] if len(a) > 2 else None
            if isinstance(d, list):
                dark.append((path, hund(d[1])))
                d = d[0]
            return [(path, "num", hund(a[0]), hund(a[1]), hund(d))]
        if t == "bool":
            d = a[0] if a else None
            return [(path, "bool", 0, 1, None if d is None else int(d))]
        if t == "text":
            return [(path, "text", 0, 0, None)]
        if t == "corners":
            return [(path, "corners", 0, 15, 15)]
        if t == "slots":
            n = -(-len(_icon_slots()) // SLOT_BITS)
            return [("%s.%d" % (path, i), "bits", 0, 0, None) for i in range(n)]
        w0, w1 = lk["line_w"]
        o0, o1 = lk["offset"]
        b0, b1 = lk["shadow_blur"]
        if t == "line":
            return [(path + ".w", "num", w0 * 100, w1 * 100, None),
                    (path + ".c", "colour", 0, 0, None)]
        if t == "shadow":
            return [(path + ".kind", "enum", lk["shadow_kinds"], None, 0),
                    (path + ".c", "colour", 0, 0, None),
                    (path + ".alpha", "num", 0, 100, None),
                    (path + ".blur", "num", b0 * 100, b1 * 100, None),
                    (path + ".dx", "int", o0, o1, None),
                    (path + ".dy", "int", o0, o1, None)]
        if t == "tshadow":
            return [(path + ".c", "colour", 0, 0, None),
                    (path + ".alpha", "num", 0, 100, None),
                    (path + ".dx", "int", o0, o1, None),
                    (path + ".dy", "int", o0, o1, None)]
        if t == "ring":
            return [(path + ".c", "colour", 0, 0, colour(a[0] if a else None)),
                    (path + ".alpha", "num", 0, 100, hund(a[1]) if len(a) > 1 else None)]
        return [(path + "." + k, "colour", 0, 0, None) for k in ("fill", "body", "eye")]

    for spec in lk["fields"]:
        path, t = spec[0], spec[1]
        if t == "button":
            for kind in lk["button_kinds"]:
                for b in lk["button"]:
                    p = "%s.%s.%s" % (path, kind, b[0])
                    out.append((p, b[1], one(p, b[1:])))
            continue
        out.append((path, "enum" if t == "role" else t, one(path, spec[1:])))
    return out, dark


def _sublist(seq, part):
    """Where `part` sits in `seq` as a run, or -1."""
    for i in range(len(seq) - len(part) + 1):
        if seq[i:i + len(part)] == part:
            return i
    return -1


def _look(th, roles):
    """The look model's tables (docs/look_2026-10.md step 5, THEMES.md's
    theme model): every field, its leaves, their kinds, ranges and
    defaults, the enum names and the object groups."""
    lk = th["look"]
    bd = lk["backdrop"]
    fields, dark = _look_fields(lk, roles)
    paths = [f[0] for f in fields]
    if len(set(paths)) != len(paths):
        raise SystemExit("theme.look: a field twice")
    groups = []
    for p in paths:
        parts = p.split(".")
        for i in range(1, len(parts)):
            g = ".".join(parts[:i])
            if g in paths:
                raise SystemExit("theme.look: %s is a field and a group" % g)
            if g not in groups:
                groups.append(g)
    # each group's fields are contiguous, so the writer opens each once
    for g in groups:
        idx = [i for i, p in enumerate(paths) if p.startswith(g + ".")]
        if idx != list(range(idx[0], idx[-1] + 1)):
            raise SystemExit("theme.look: group %s is not contiguous" % g)
    enums, leaves = [], []
    for path, t, lv in fields:
        for name, kind, lo, hi, d in lv:
            if kind == "enum":
                names = lo
                if d is not None and not isinstance(d, int):
                    d = names.index(d)
                lo, hi = _sublist(enums, names), len(names)
                if lo < 0:
                    lo = len(enums)
                    enums.extend(names)
            leaves.append((name, kind, lo, hi, d))
    btn, _ = _look_fields({**lk, "fields": [["b", "button"]], "button_kinds": ["k"]})
    leaf_at = [l[0] for _p, _t, lv in fields for l in lv]
    btn_leaves = [l for _p, _t, lv in btn for l in lv]

    def term(v):
        return "INT32_MIN" if v is None else "%d" % v

    h = ["// The look (docs/look_2026-10.md step 5): the theme model's fields, each",
         "// one or more leaves; a leaf's kind, its range (an enum's first name and",
         "// count), its default (MOY_THEME_NONE: silent, the renderer derives it).",
         "#define MOY_THEME_LEAVES %d" % len(leaves),
         "#define MOY_THEME_LOOK_FIELDS %d" % len(fields),
         "#define MOY_THEME_LOOK_GROUPS %d" % len(groups),
         "#define MOY_THEME_ENUM_NAMES %d" % len(enums),
         "#define MOY_THEME_BTN_KINDS %d" % len(lk["button_kinds"]),
         "#define MOY_THEME_BTN_LEAVES %d" % len(btn_leaves),
         "#define MOY_THEME_BTN_LEAF0 %d  // buttons.%s's first leaf" % (
             [l[0] for l in leaves].index("buttons.%s.%s" % (lk["button_kinds"][0],
                                                             lk["button"][0][0])),
             lk["button_kinds"][0]),
         "#define MOY_THEME_PAINT_STOPS %d" % lk["paint_stops"],
         "#define MOY_THEME_PAINTS_CAP %d" % lk["paints_cap"],
         "#define MOY_THEME_ENTRIES_CAP %d" % lk["entries_cap"],
         "#define MOY_THEME_TILES_CAP %d" % lk["tiles_cap"],
         "#define MOY_THEME_APPBTN_CAP %d" % lk["app_buttons_cap"],
         "#define MOY_THEME_MAPNAME_MAX %d" % lk["name_max"],
         "#define MOY_THEME_LOOK_TEXT_MAX %d" % lk["text_max"],
         "#define MOY_THEME_PAINT_MODES %d" % len(lk["paint_modes"]),
         "// A backdrop (docs/media/look_2026-10/GAPS.md gap 9): per surface a list",
         "// of shapes, each kind's coordinate count (-1: [x, y] points).",
         "#define MOY_THEME_BD_SURFACES %d" % len(bd["surfaces"]),
         "#define MOY_THEME_BD_KINDS %d" % len(bd["kinds"]),
         "#define MOY_THEME_BD_SHAPES %d" % bd["shapes"],
         "#define MOY_THEME_BD_STOPS %d" % bd["stops"],
         "#define MOY_THEME_BD_POOL %d" % bd["pool"],
         "#define MOY_THEME_BD_POINTS_MIN %d" % bd["points"][0],
         "#define MOY_THEME_BD_POINTS %d" % bd["points"][1],
         "#define MOY_THEME_BD_AT %d" % max([2 * bd["points"][1]] + [a for a in bd["at"] if a]),
         "#define MOY_THEME_BD_LO (%d)" % bd["coord"][0],
         "#define MOY_THEME_BD_HI %d" % bd["coord"][1],
         "extern const char *const moy_theme_bd_surfaces[MOY_THEME_BD_SURFACES];",
         "extern const char *const moy_theme_bd_kinds[MOY_THEME_BD_KINDS];",
         "extern const int8_t moy_theme_bd_at[MOY_THEME_BD_KINDS];",
         "// The leaves whose default differs in a dark variant: (leaf, value).",
         "#define MOY_THEME_DARK_DEFS %d" % len(dark),
         "extern const int32_t moy_theme_dark_defs[MOY_THEME_DARK_DEFS][2];",
         "enum {",
         *["    MOY_THEME_LK_%s = %d," % (_ident(k), i) for i, k in enumerate(_LEAF_KINDS)],
         "};",
         "enum {",
         *["    MOY_THEME_FT_%s = %d," % (_ident(k), i) for i, k in enumerate(_FIELD_TYPES)],
         "};",
         "typedef struct { uint8_t kind; int32_t lo, hi, def; } moy_theme_leaf_t;",
         "typedef struct { const char *path; uint8_t type, n; uint16_t leaf; } moy_theme_field_t;",
         "extern const moy_theme_leaf_t moy_theme_leaves[MOY_THEME_LEAVES];",
         "extern const char *const moy_theme_leaf_names[MOY_THEME_LEAVES];",
         "extern const moy_theme_field_t moy_theme_fields[MOY_THEME_LOOK_FIELDS];",
         "extern const char *const moy_theme_look_groups[MOY_THEME_LOOK_GROUPS];",
         "extern const char *const moy_theme_enum_names[MOY_THEME_ENUM_NAMES];",
         "extern const char *const moy_theme_btn_kinds[MOY_THEME_BTN_KINDS];",
         "// An app_buttons entry's leaves: a kind's button leaves, in order.",
         "extern const moy_theme_field_t moy_theme_btn_fields[%d];" % len(btn),
         "#define MOY_THEME_BTN_FIELDS %d" % len(btn),
         "extern const char *const moy_theme_paint_modes[MOY_THEME_PAINT_MODES];",
         "// RGB colours (docs/look_2026-10.md step 5): MOY64 as 0xrrggbb, and the",
         "// WCAG luminance (x10000, as moy_theme_lum) of an RGB565 channel.",
         "extern const uint32_t moy_theme_moy64[64];",
         "extern const uint16_t moy_theme_lin5[32], moy_theme_lin6[64];"]
    c = ["const moy_theme_leaf_t moy_theme_leaves[MOY_THEME_LEAVES] = {"]
    for name, kind, lo, hi, d in leaves:
        c.append("    {MOY_THEME_LK_%s, %s, %s, %s},  // %s" % (
            _ident(kind), term(lo), term(hi), term(d), name))
    c.append("};\n")
    c.append("const char *const moy_theme_leaf_names[MOY_THEME_LEAVES] = {")
    c.extend("    %s," % _c_str(l[0]) for l in leaves)
    c.append("};\n")

    def field_rows(fs):
        rows, at = [], 0
        for path, t, lv in fs:
            rows.append("    {%s, MOY_THEME_FT_%s, %d, %d}," % (_c_str(path), _ident(t), len(lv), at))
            at += len(lv)
        return rows
    c.append("const int32_t moy_theme_dark_defs[MOY_THEME_DARK_DEFS][2] = {")
    c.extend("    {%d, %d},  // %s" % (leaf_at.index(n), v, n) for n, v in dark)
    c.append("};\n")
    c.append("const moy_theme_field_t moy_theme_fields[MOY_THEME_LOOK_FIELDS] = {")
    c.extend(field_rows(fields))
    c.append("};\n")
    c.append("const moy_theme_field_t moy_theme_btn_fields[%d] = {" % len(btn))
    c.extend(field_rows([(p.split(".", 2)[2], t, lv) for p, t, lv in btn]))
    c.append("};\n")
    for decl, seq in (("moy_theme_look_groups[MOY_THEME_LOOK_GROUPS]", groups),
                      ("moy_theme_enum_names[MOY_THEME_ENUM_NAMES]", enums),
                      ("moy_theme_btn_kinds[MOY_THEME_BTN_KINDS]", lk["button_kinds"]),
                      ("moy_theme_paint_modes[MOY_THEME_PAINT_MODES]", lk["paint_modes"]),
                      ("moy_theme_bd_surfaces[MOY_THEME_BD_SURFACES]", bd["surfaces"]),
                      ("moy_theme_bd_kinds[MOY_THEME_BD_KINDS]", bd["kinds"])):
        c.append("const char *const %s = {" % decl)
        c.extend("    %s," % _c_str(n) for n in seq)
        c.append("};\n")
    c.append("const int8_t moy_theme_bd_at[MOY_THEME_BD_KINDS] = {%s};\n" % ", ".join(
        "-1" if a is None else "%d" % a for a in bd["at"]))
    m = _moy64()
    c.append("const uint32_t moy_theme_moy64[64] = {")
    for i in range(0, 64, 8):
        c.append("    %s," % ", ".join("0x%06x" % ((r << 16) | (g << 8) | b) for r, g, b in m[i:i + 8]))
    c.append("};\n")

    def lin(v):
        v /= 255.0
        return v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4
    l5 = [round(10000 * lin((i << 3) | (i >> 2))) for i in range(32)]
    l6 = [round(10000 * lin((i << 2) | (i >> 4))) for i in range(64)]
    c.append("const uint16_t moy_theme_lin5[32] = {%s};\n" % ", ".join(map(str, l5)))
    c.append("const uint16_t moy_theme_lin6[64] = {%s};\n" % ", ".join(map(str, l6)))
    return h, c


def _recolour(th, roles, flags):
    """The accent-and-tint derivation's tables (docs/theming_2026-09.md
    §4.10, moy_theme_derive): the accents, the presets (an accent in a dark
    and a light value, docs/look_2026-10.md step 27), the tints' ramps and
    the role classes its steps rewrite."""
    lum = _luminance()
    rc = th["recolour"]

    def clears(a, b):
        hi, lo = max(lum[a], lum[b]), min(lum[a], lum[b])
        return (hi + 500) * 10 >= th["contrast"] * (lo + 500)

    def role(name):
        if name not in roles or flags[roles.index(name)]:
            raise SystemExit("theme.recolour: %r is no colour role" % name)
        return roles.index(name)

    accents, tints, presets = th["accents"], th["tints"], th["presets"]
    for name, a, deep in accents:
        if not (0 <= a < 64 and 0 <= deep < 64 and clears(a, 0)):
            raise SystemExit("theme.accents: %s is two palette indices, A one black clears"
                             % name)
    for name, dark, light in presets:
        if not (0 <= dark < 64 and 0 <= light < 64 and clears(dark, 0) and clears(light, 7)):
            raise SystemExit("theme.presets: %s is two palette indices, dark one black "
                             "clears, light one white clears" % name)
    for name, ramp in tints:
        if not ramp or any(not 0 < v < 64 or v == 7 for v in ramp):
            raise SystemExit("theme.tints: %s's ramp is palette indices, never 0 or 7" % name)
    names = [n for n, *_ in accents + presets] + [n for n, _r in tints]
    if len(set(n for n, *_ in accents + presets)) != len(accents) + len(presets) or \
            len(set(n for n, _r in tints)) != len(tints) or \
            len(set(a for _n, a, _d in accents + presets)) != len(accents) + len(presets):
        raise SystemExit("theme.accents / theme.presets / theme.tints: a name or an accent "
                         "(a preset's dark value) twice")
    if any(len(n) > 15 for n in names):
        raise SystemExit("theme.accents / theme.tints: a name of at most 15 characters")
    classes = ("background", "line", "accent", "tied", "accent_ink", "content")
    lists = [[role(r) for r in rc[k]] for k in classes]
    cmax = max(len(v) for v in lists)
    rmax = max(len(r) for _n, r in tints)
    greys = rc["dim_greys"]
    dims = [(role(r), role(f), [role(b) for b in bgs]) for r, f, bgs in rc["dim_ink"]]
    if any(not 1 <= len(b) <= 3 for _r, _f, b in dims):
        raise SystemExit("theme.recolour.dim_ink: one to three backgrounds each")
    h = ["// Accent and tint (docs/theming_2026-09.md §4.10, moy_theme_derive): the",
         "// accents [A, deep], the presets [dark, light] (an accent index past",
         "// MOY_THEME_ACCENTS names one), the tints' ramps ([0] the length, then",
         "// dark to light), and the role classes, each 0xff past its end.",
         "#define MOY_THEME_ACCENTS %d" % len(accents),
         "#define MOY_THEME_PRESETS %d" % len(presets),
         "#define MOY_THEME_TINTS %d" % len(tints),
         "#define MOY_THEME_RAMP_MAX %d" % rmax,
         "#define MOY_THEME_CLASS_MAX %d" % cmax,
         "#define MOY_THEME_DIM_INKS %d" % len(dims),
         "#define MOY_THEME_DIM_GREYS %d" % len(greys),
         "enum {",
         *["    MOY_THEME_CL_%s = %d," % (_ident(k), i) for i, k in enumerate(classes)],
         "    MOY_THEME_CLASSES = %d," % len(classes),
         "};",
         "extern const char *const moy_theme_accent_names[MOY_THEME_ACCENTS];",
         "extern const uint8_t moy_theme_accents[MOY_THEME_ACCENTS][2];",
         "extern const char *const moy_theme_preset_names[MOY_THEME_PRESETS];",
         "extern const uint8_t moy_theme_presets[MOY_THEME_PRESETS][2];",
         "extern const char *const moy_theme_tint_names[MOY_THEME_TINTS];",
         "extern const uint8_t moy_theme_tints[MOY_THEME_TINTS][MOY_THEME_RAMP_MAX + 1];",
         "extern const uint8_t moy_theme_classes[MOY_THEME_CLASSES][MOY_THEME_CLASS_MAX];",
         "// Each dim ink: the role, its fallback, its backgrounds (0xff past the end).",
         "extern const uint8_t moy_theme_dim_inks[MOY_THEME_DIM_INKS][5];",
         "extern const uint8_t moy_theme_dim_greys[MOY_THEME_DIM_GREYS];"]
    c = ["const char *const moy_theme_accent_names[MOY_THEME_ACCENTS] = {"]
    c.extend("    %s," % _c_str(n) for n, _a, _d in accents)
    c.append("};\n")
    c.append("const uint8_t moy_theme_accents[MOY_THEME_ACCENTS][2] = {%s};\n"
             % ", ".join("{%d, %d}" % (a, d) for _n, a, d in accents))
    c.append("const char *const moy_theme_preset_names[MOY_THEME_PRESETS] = {")
    c.extend("    %s," % _c_str(n) for n, _d, _l in presets)
    c.append("};\n")
    c.append("const uint8_t moy_theme_presets[MOY_THEME_PRESETS][2] = {%s};\n"
             % ", ".join("{%d, %d}" % (d, li) for _n, d, li in presets))
    c.append("const char *const moy_theme_tint_names[MOY_THEME_TINTS] = {")
    c.extend("    %s," % _c_str(n) for n, _r in tints)
    c.append("};\n")
    c.append("const uint8_t moy_theme_tints[MOY_THEME_TINTS][MOY_THEME_RAMP_MAX + 1] = {")
    c.extend("    {%s},  // %s" % (", ".join(map(str, [len(r)] + r)), n) for n, r in tints)
    c.append("};\n")
    c.append("const uint8_t moy_theme_classes[MOY_THEME_CLASSES][MOY_THEME_CLASS_MAX] = {")
    for k, v in zip(classes, lists):
        c.append("    {%s},  // %s" % (", ".join(map(str, v + [255] * (cmax - len(v)))), k))
    c.append("};\n")
    c.append("const uint8_t moy_theme_dim_inks[MOY_THEME_DIM_INKS][5] = {%s};\n"
             % ", ".join("{%s}" % ", ".join(map(str, [r, f] + b + [255] * (3 - len(b))))
                         for r, f, b in dims))
    c.append("const uint8_t moy_theme_dim_greys[MOY_THEME_DIM_GREYS] = {%s};\n"
             % ", ".join(map(str, greys)))
    return h, c


def generate_strings(strings):
    """moy_str_table.h/.c: the ids, their names and English."""
    ids = list(strings)
    for sid, text in strings.items():
        if not re.match(r"^[a-z_]+\.[a-z_]+$", sid):
            raise SystemExit("%s: a string id is section.name" % sid)
        bad = [m for m in re.findall(r"%(?:08x|.)", text.replace("%%", ""))
               if m not in ("%s", "%d", "%u", "%08x")]
        if bad:
            raise SystemExit("%s: a conversion outside %%s %%d %%u %%08x" % sid)
    head = ("// GENERATED by tools/gen_ui_tables.py from strings/en.json.\n"
            "// Do not edit: change the data and regenerate "
            "(tests/test_ui_tables.py).\n")
    h = [head, "#ifndef MOY_STR_TABLE_H\n#define MOY_STR_TABLE_H\n",
         "#define MOY_STRINGS %d\n" % len(ids), "// The string ids.", "enum {"]
    for i, sid in enumerate(ids):
        h.append("    MOY_S_%s = %d," % (_ident(sid), i))
    h.append("};\n")
    h.append("extern const char *const moy_str_ids[MOY_STRINGS];")
    h.append("extern const char *const moy_str_en[MOY_STRINGS];")
    h.append("\n#endif // MOY_STR_TABLE_H")
    c = [head, '#include "moy_str_table.h"\n']
    for decl, seq in (("moy_str_ids", ids), ("moy_str_en", [strings[i] for i in ids])):
        c.append("const char *const %s[MOY_STRINGS] = {" % decl)
        for s in seq:
            c.append("    %s," % _c_str(s))
        c.append("};\n")
    return "\n".join(h) + "\n", "\n".join(c)


def load(d):
    with open(os.path.join(d, "style.json")) as f:
        return json.load(f)


def load_strings(d):
    with open(os.path.join(d, "strings", "en.json")) as f:
        return json.load(f)["strings"]


def outputs(ui_dir=DIR, str_dir=STR_DIR):
    """[(path, text)] of every generated file."""
    h, c = generate(load(ui_dir), ui_dir)
    sh, sc = generate_strings(load_strings(str_dir))
    return [(os.path.join(ui_dir, "moy_ui_tables.h"), h),
            (os.path.join(ui_dir, "moy_ui_tables.c"), c),
            (os.path.join(str_dir, "moy_str_table.h"), sh),
            (os.path.join(str_dir, "moy_str_table.c"), sc)]


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--dir", default=DIR)
    ap.add_argument("--str-dir", default=STR_DIR)
    ap.add_argument("--check", action="store_true",
                    help="fail when the committed tables differ")
    a = ap.parse_args(argv)
    out = outputs(a.dir, a.str_dir)
    if a.check:
        for p, text in out:
            if not os.path.exists(p) or open(p).read() != text:
                print("%s is stale: run tools/gen_ui_tables.py" % p)
                return 1
        return 0
    for p, text in out:
        with open(p, "w") as f:
            f.write(text)
    return 0


if __name__ == "__main__":
    sys.exit(main())
